// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import path from "node:path";
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Prisma 7 resolves a relative sqlite `file:` URL against the folder of this
// config file (the project root); Prisma 6 resolved it against
// prisma/schema.prisma. Every existing install's `file:./dev.db` means
// prisma/dev.db, so keep that meaning here, and in src/lib/prisma.ts (which
// must open the same file the CLI migrates). Absolute paths (Docker, Pinokio,
// the Windows app) and non-file URLs pass through untouched.
function databaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("Cannot resolve environment variable: DATABASE_URL");
  if (url.startsWith("file:") && !path.isAbsolute(url.slice("file:".length))) {
    const absolute = path.join(process.cwd(), "prisma", url.slice("file:".length));
    return `file:${absolute.split(path.sep).join("/")}`;
  }
  return url;
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl(),
  },
});
